    var decoder = NimbusJwtDecoder.withJwkSetUri(jwkUri)
        .jwsAlgorithm(SignatureAlgorithm.RS256)   // cố định thuật toán -> chặn alg confusion
        .build();
    decoder.setJwtValidator(JwtValidators.createDefaultWithIssuer(issuer));
    return decoder;
}

